#include "common.h"
#include "sel.h"
#include "xin.h"

#include <ctype.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

static int trailing_space_only(const char *s, int used)
{
    while (s[used] != '\0') {
        if (!isspace((unsigned char)s[used]))
            return 0;
        used++;
    }
    return 1;
}

static int blob_has(const char *path, const char *name)
{
    FILE *fp = fopen(path, "r");
    char line[LINE_LEN], row_name[NAME_LEN], cls[32];
    int id, used;

    if (fp == NULL)
        return 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "CALL %63s %d %31s%n", row_name, &id, cls, &used) == 3 &&
            trailing_space_only(line, used) && strcmp(cls, "live") == 0 &&
            strcmp(row_name, name) == 0) {
            fclose(fp);
            return 1;
        }
    }
    fclose(fp);
    return 0;
}

static int read_spool_call(const char *path, char *name, unsigned name_len)
{
    FILE *fp;
    char line[LINE_LEN], extra[2];

    fp = fopen(path, "r");
    if (fp == NULL)
        return -1;
    if (fgets(line, sizeof(line), fp) == NULL ||
        sscanf(line, "%63s %1s", name, extra) != 1 || strlen(name) >= name_len) {
        fclose(fp);
        return -1;
    }
    while (fgets(line, sizeof(line), fp) != NULL) {
        char *p = line;
        while (*p != '\0') {
            if (!isspace((unsigned char)*p++)) {
                fclose(fp);
                return -1;
            }
        }
    }
    fclose(fp);
    return 0;
}

static int read_knit_stamp(char *stamp, size_t cap)
{
    FILE *fp;
    char line[64], extra[2];
    size_t i;

    fp = fopen(KNIT_OK_PATH, "r");
    if (fp == NULL)
        return -1;
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (sscanf(line, "%8s %1s", stamp, extra) != 1 || strlen(stamp) != STAMP_LEN || cap < 9)
        return -1;
    for (i = 0; i < STAMP_LEN; i++)
        if (!isdigit((unsigned char)stamp[i]) && !(stamp[i] >= 'a' && stamp[i] <= 'f'))
            return -1;
    return 0;
}

int cmd_spin(int argc, char **argv)
{
    const char *blob = CAPSET_PATH;
    const char *spool;
    char call[NAME_LEN], stamp[STAMP_LEN + 1], knit_stamp[STAMP_LEN + 1];
    char loaded[32];
    const char *status;
    int mark = 0, covered;
    FILE *fp;

    unlink(ACCEPT_PATH);
    if (argc == 1) {
        spool = argv[0];
    } else if (argc == 3 && strcmp(argv[0], "--blob") == 0) {
        blob = argv[1];
        spool = argv[2];
    } else {
        fprintf(stderr, "usage: nockreel spin [--blob PATH] SPOOL\n");
        return 2;
    }

    if (read_spool_call(spool, call, sizeof(call)) != 0)
        return 2;
    if (xin_blob(blob, &mark, stamp, sizeof(stamp)) != 0 || sel_bank(0) != 0 ||
        read_knit_stamp(knit_stamp, sizeof(knit_stamp)) != 0 ||
        strcmp(stamp, knit_stamp) != 0) {
        return 1;
    }

    covered = blob_has(blob, call);
    status = covered ? "replayed" : "unsupported";
    snprintf(loaded, sizeof(loaded), "table:%s", knit_stamp);
    printf("{\"loaded\":\"%s\",\"status\":\"%s\",\"call\":\"%s\"}\n",
           loaded, status, call);

    fp = fopen(LOADED_SET_PATH, "w");
    if (fp == NULL)
        return 1;
    if (fprintf(fp, "%s\n", loaded) < 0 || fclose(fp) != 0)
        return 1;
    fp = fopen(ACCEPT_PATH, "w");
    if (fp == NULL)
        return 1;
    if (fputs("1\n", fp) == EOF || fclose(fp) != 0) {
        unlink(ACCEPT_PATH);
        return 1;
    }
    (void)mark;
    return 0;
}
